/*
 * This file was generated by the Gradle 'init' task.
 *
 * This generated file contains a sample Java application project to get you started.
 * For more details on building Java & JVM projects, please refer to https://docs.gradle.org/8.14.2/userguide/building_java_projects.html in the Gradle documentation.
 */

plugins {
    // Apply the application plugin to add support for building a CLI application in Java.
    application
}

repositories {
    // Use Maven Central for resolving dependencies.
    mavenCentral()
}

dependencies {
    // Use JUnit Jupiter for testing.
    testImplementation(libs.junit.jupiter)

    testRuntimeOnly("org.junit.platform:junit-platform-launcher")

    // This dependency is used by the application.
    implementation(libs.guava)

    implementation("io.github.cdimascio:dotenv-java:3.2.0")
    implementation("com.mysql:mysql-connector-j:8.0.33")
    implementation("org.xerial:sqlite-jdbc:3.50.1.0");

    // The following are
    // groupId:     com.formdev
    // artifactId:  flatlaf-intellij-themes
    // version:     3.6 (the current latest version)
    implementation("com.formdev:flatlaf:3.6")
    implementation("com.formdev:flatlaf-intellij-themes:3.6")
}

// Apply a specific Java toolchain to ease working on different environments.
java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(21)
    }
}

application {
    // Define the main class for the application.
    mainClass = "org.YAPM.App"
}

tasks.named<Test>("test") {
    // Use JUnit Platform for unit tests.
    useJUnitPlatform()
    testLogging {
      showStandardStreams = true
    }

    // The backend DB tests require a running MySQL instance, which is only
    // available in the Ubuntu CI job. They are skipped when SKIP_DB_TESTS is set
    // (e.g. the macOS/Windows CI jobs that have no MySQL service).
    if (System.getenv("SKIP_DB_TESTS") == "true") {
      exclude(
        "**/CloudDbConnectionTest*",
        "**/DBConnectionTest*",
        "**/SetupDBTest*",
        "**/RegisterUserTest*",
        "**/LoginUserTest*",
      )
    }

    // The following tests hit a real Supabase bucket and require credentials plus
    // network access that aren't available on CI.
    if (System.getenv("CI") == "true") {
      exclude(
        "**/SupabaseUtilsTest*",
        "**/RegisterUserTest*",
        "**/LoginUserTest*",
      )
    }
}
